final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // Preserve the current position of the buffer
    int oldPos = classFileBuffer.position();
    // Seek to the start of the constant pool entry (assuming the index is an offset)
    classFileBuffer.position(constantPoolEntryIndex);
    // Read the tag byte
    byte tag = classFileBuffer.get();
    // CONSTANT_Utf8 has tag value 1
    if (tag != 1) {
        // Not a UTF-8 entry; restore position and return null
        classFileBuffer.position(oldPos);
        return null;
    }
    // Read the length of the UTF-8 string (unsigned short)
    int length = classFileBuffer.getShort() & 0xFFFF;
    // Read the UTF-8 bytes
    byte[] bytes = new byte[length];
    classFileBuffer.get(bytes);
    // Decode the bytes into a String using UTF-8
    String str = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    // Ensure the provided char buffer is large enough
    if (charBuffer.length < str.length()) {
        throw new IllegalArgumentException("charBuffer too small for UTF-8 string");
    }
    // Copy the decoded characters into the supplied buffer
    str.getChars(0, str.length(), charBuffer, 0);
    // Restore the original buffer position
    classFileBuffer.position(oldPos);
    return str;
}

